#[tokio::test]
async fn persist__order_persist_first() {
    crate::check_persist(
        order::code(order::State::Draft),
        |stored| {
            let actual = order::from_code(stored)?;
            let step = order::apply(order::State::Draft, order::Event::Next, actual)?;
            Ok((order::code(step.to), step.changed))
        },
        Ok((order::code(order::State::Paid), true)),
        order::code(order::State::Paid),
    ).await;
}

#[tokio::test]
async fn persist__order_persist_retry() {
    crate::check_persist(
        order::code(order::State::Paid),
        |stored| {
            let actual = order::from_code(stored)?;
            let step = order::apply(order::State::Draft, order::Event::Next, actual)?;
            Ok((order::code(step.to), step.changed))
        },
        Ok((order::code(order::State::Paid), false)),
        order::code(order::State::Paid),
    ).await;
}

#[tokio::test]
async fn persist__order_persist_conflict() {
    crate::check_persist(
        order::code(order::State::Shipped),
        |stored| {
            let actual = order::from_code(stored)?;
            let step = order::apply(order::State::Draft, order::Event::Next, actual)?;
            Ok((order::code(step.to), step.changed))
        },
        Err(crate::Expected { code: Code::Conflict, expected: Some(1), actual: Some(3), event: Some(1) }),
        order::code(order::State::Shipped),
    ).await;
}

